    .io_enq_bits  (int8Req ? lineData8_REG : casez_tmp_16),
    .io_deq_ready (mem_wnext | dmaBusy & mem_ready | ~dmaBusy),
    .io_deq_valid (_lineFifo_io_deq_valid),
    .io_deq_bits  (mem_wline),
    .io_count     (_lineFifo_io_count)
  );
  assign s_axi_awready = awreadyReg;
  assign s_axi_wready = wreadyReg;
  assign s_axi_bresp = 2'h0;
  assign s_axi_bvalid = bvalidReg;
  assign s_axi_arready = arreadyReg;
  assign s_axi_rdata =
    raddrWord == 6'h1
      ? {24'h0, qDone, qBusy, ldDone, ldBusy, dmaDone, dmaBusy, done, busy}
      : raddrWord == 6'hA
          ? destAddr
          : raddrWord == 6'hB
              ? destStride
              : raddrWord == 6'hC
                  ? aSrcAddr
                  : raddrWord == 6'hD
                      ? bSrcAddr
                      : raddrWord == 6'hE
                          ? srcStride
                          : raddrWord == 6'h16
                              ? {23'h0, int8Req, 3'h0, outShift}
                              : raddrWord == 6'hF
                                  ? {30'h0, bPanelUse}
                                  : raddrWord == 6'h10
                                      ? {30'h0, bPanelLoad}
                                      : raddrWord == 6'h15
                                          ? {28'h0, 4'h8 - _descQ_io_count}
                                          : raddrWord == 6'h2
                                              ? {24'h0, kLen}
                                              : raddrWord == 6'h3
                                                  ? {28'h0, loadK}
                                                  : raddrWord == 6'h4
                                                      ? {29'h0, loadLane}
                                                      : raddrWord == 6'h7
                                                          ? {26'h0, resultIdx}
                                                          : _GEN_15
                                                              ? casez_tmp_26
                                                              : raddrWord == 6'h9
                                                                  ? 32'h44008
                                                                  : 32'h0;
  assign s_axi_rresp = 2'h0;
  assign s_axi_rvalid = rvalidReg;
  assign mem_req_valid = dmaBusy & _lineFifo_io_deq_valid | ldBusy & ldReq & ~dmaBusy;
  assign mem_req_write = dmaBusy;
  assign mem_req_addr =
    dmaBusy
      ? dmaAddr
      : burstOK
          ? ldBase
          : {26'h0, ldChunk, 4'h0} + ldBase + {29'h0, ldLane} * effSrcStride;
  assign mem_req_lines =
    {2'h0, dmaBusy ? {1'h0, wBurstLines} : burstOK ? {_ldLines_T_1, 3'h0} : 6'h1};
endmodule

